from json import loads, JSONDecodeError

def safe_json_parse(json_str):
    """
    Safely parse a JSON string into a Python object.

    Args:
        json_str (str): The JSON string to parse.

    Returns:
        dict or list: The parsed JSON object.
    """
    try:
        # Attempt to load the JSON string
        return loads(json_str)
    except JSONDecodeError as e:
        # If decoding fails, print an error message and return None
        print(f"Failed to decode JSON: {e}")
        return None

def safe_nested_parse(json_str, max_depth=5):
    """
    Safely parse a nested JSON string into a Python object with deep fallbacks.

    Args:
        json_str (str): The JSON string to parse.
        max_depth (int): The maximum depth to recursively search. Defaults to 5.

    Returns:
        dict or list: The parsed JSON object, or None if parsing fails.
    """
    def recursive_parse(json_obj, current_depth):
        # If the maximum depth is reached, return None
        if current_depth >= max_depth:
            return None

        # Check for array elements
        if isinstance(json_obj, list):
            return [recursive_parse(element, current_depth + 1) for element in json_obj]

        # Check for object keys
        elif isinstance(json_obj, dict):
            new_dict = {}
            for key, value in json_obj.items():
                new_key = safe_str(key)
                new_value = recursive_parse(value, current_depth + 1)
                if new_value is not None:
                    new_dict[new_key] = new_value
            return new_dict

        # If none of the above, return the parsed object
        else:
            return json_obj

    def safe_str(s):
        # Safely replace nested JSON with a fallback string
        while '}' in s or ',' in s:
            start = 0
            end = s.find('{"', start)
            if end == -1:
                break
            new_s = s[:start] + '"' + s[end+2:] + '"'
            s = new_s
        return s

    # Attempt to parse the JSON string
    return recursive_parse(json_str, 0)

# Test usage
json_str = '{"key": {"nested_key": "value"}}'
print(safe_nested_parse(json_str))
